import {clamp,escapeHTML as esc} from './core.js';
export async function importXML(a,text){if(text.length>25*1024*1024)throw new Error('XMLは25 MB以下にしてください。');const doc=new DOMParser().parseFromString(text,'application/xml');if(doc.querySelector('parsererror')||!doc.querySelector('DJ_PLAYLISTS'))throw new Error('rekordbox XML形式ではありません。');let matched=0,unmatched=0,ambiguous=0;const idMap=new Map();for(const node of doc.querySelectorAll('COLLECTION > TRACK')){const location=node.getAttribute('Location')||'';let filename;try{filename=decodeURIComponent(location.split('/').pop());}catch{filename=location.split('/').pop();}const choices=[...a.tracks.values()].filter(t=>t.filename===filename);if(choices.length!==1){choices.length>1?ambiguous++:unmatched++;continue;}const t=choices[0],bpm=Number(node.getAttribute('AverageBpm'));if(bpm>=20&&bpm<=400)t.bpm=bpm;t.artist=node.getAttribute('Artist')||t.artist;t.name=node.getAttribute('Name')||t.name;t.key=node.getAttribute('Tonality')||t.key;t.comment=node.getAttribute('Comments')||t.comment;t.originalLocation=location;const tempo=node.querySelector('TEMPO');if(tempo)t.gridOffset=clamp(Number(tempo.getAttribute('Inizio')),0,t.duration);for(const mark of node.querySelectorAll('POSITION_MARK')){const num=Number(mark.getAttribute('Num')),v=Number(mark.getAttribute('Start'));if(Number(mark.getAttribute('Type'))===0&&num>=0&&num<8&&Number.isInteger(num)&&Number.isFinite(v))t.cues[num]=clamp(v,0,t.duration);}idMap.set(node.getAttribute('TrackID'),t.id);await a.putTrack(t);matched++;}for(const node of doc.querySelectorAll('PLAYLISTS NODE[Type="1"]')){const ids=Array.from(node.children).filter(n=>n.tagName==='TRACK').map(n=>idMap.get(n.getAttribute('Key'))).filter(Boolean);if(ids.length)a.s.playlists.push({id:crypto.randomUUID(),name:node.getAttribute('Name')||'Imported crate',tracks:[...new Set(ids)]});}a.render();a.applyAll();a.save();a.modal('XMLの読み込み結果',`<p>${matched}曲の曲情報・BPM・ホットキューを更新しました。</p><p>音源未一致：${unmatched}曲 / 同名で判別できない音源：${ambiguous}曲</p><div class="note">音声データはXMLに含まれません。同じファイル名の音源を先に取り込んでください。可変テンポは最初のTEMPOのみ、ホットキューは0〜7のみ読み込みます。</div>`);}
export function exportXML(a,prefix){if(!/^file:\/\//.test(prefix))throw new Error('実際の音源フォルダーをfile:// URLで指定してください。');prefix=prefix.replace(/\/?$/,'/');const doc=document.implementation.createDocument(null,'DJ_PLAYLISTS'),root=doc.documentElement;root.setAttribute('Version','1.0.0');const make=(tag,attrs,parent)=>{const el=doc.createElement(tag);for(const[k,v]of Object.entries(attrs))el.setAttribute(k,String(v));parent.append(el);return el;};make('PRODUCT',{Name:'SeekDeck',Version:'0.1',Company:'SeekDeck'},root);const col=make('COLLECTION',{Entries:a.tracks.size},root),idMap=new Map();let n=1;for(const t of a.tracks.values()){const id=n++;idMap.set(t.id,id);const row=make('TRACK',{TrackID:id,Name:t.name,Artist:t.artist,AverageBpm:t.bpm,TotalTime:Math.floor(t.duration),Tonality:t.key||'',Comments:t.comment||'',Location:t.originalLocation||prefix+encodeURIComponent(t.filename||t.name+'.wav')},col);make('TEMPO',{Inizio:t.gridOffset||0,Bpm:t.bpm,Metro:'4/4',Battito:1},row);(t.cues||[]).forEach((v,i)=>{if(v!=null)make('POSITION_MARK',{Name:String.fromCharCode(65+i),Type:0,Start:v,Num:i},row);});}const playlists=make('PLAYLISTS',{},root),p=make('NODE',{Type:0,Name:'ROOT',Count:a.s.playlists.length},playlists);for(const crate of a.s.playlists){const keys=crate.tracks.map(id=>idMap.get(id)).filter(Boolean),c=make('NODE',{Type:1,Name:crate.name,KeyType:0,Entries:keys.length},p);keys.forEach(key=>make('TRACK',{Key:key},c));}a.downloadBlob(new Blob(['<?xml version="1.0" encoding="UTF-8"?>\n',new XMLSerializer().serializeToString(doc)],{type:'application/xml'}),'SeekDeck-rekordbox.xml');}
